{"cmd":"python3 - <<'PY'
from pypdf import PdfReader
reader = PdfReader('/root/sc100-blank.pdf')
fields = reader.get_fields() or {}

names = [
    'SC-100[0].Page3[0].List5[0].Lia[0].Checkbox5cb[0]',
    'SC-100[0].Page3[0].List5[0].Lib[0].Checkbox5cb[0]',
    'SC-100[0].Page3[0].List5[0].Lic[0].Checkbox5cb[0]',
    'SC-100[0].Page3[0].List5[0].Lid[0].Checkbox5cb[0]',
    'SC-100[0].Page3[0].List5[0].Lie[0].Checkbox5cb[0]',
]

for name in names:
    field = fields.get(name)
    if not field:
        print('missing', name)
        continue
    parent = field['/Parent']
    kids = parent.get('/Kids', [])
    # find widget rects matching name
    rects = []
    for kid in kids:
        if kid.get('/T') == name.split('.')[-1]:
            rects.append(kid.get('/Rect'))
    # if no per-kid by name, print all kids
    print('---', name)
    if rects:
        for r in rects:
            print(' rect', r)
    else:
        for kid in kids:
            print(' kid', kid.get('/T'), kid.get('/Rect'))
PY"}

